/* Footnotes render subdued — smaller and muted vs. the body copy,
     with an auto separator and an auto-revealed "Footnotes" heading
     (GFM emits it sr-only; no need to hand-write a heading per post). */
  .prose .footnotes {
    margin-top: 2.5rem;
    padding-top: 1.25rem;
    border-top: 1px solid rgb(203 213 225 / 0.7); /* slate-300 */
    font-size: 0.8rem;
    line-height: 1.55;
    color: rgb(100 116 139); /* slate-500 */
  }
  .dark .prose .footnotes {
    border-top-color: rgb(51 65 85 / 0.7); /* slate-700 */
    color: rgb(148 163 184); /* slate-400 */
  }
  /* Un-hide the screen-reader-only GFM heading, styled to match the subdued look */
  .prose .footnotes #footnote-label {
    position: static;
    width: auto;
    height: auto;
    margin: 0 0 0.6rem;
    padding: 0;
    overflow: visible;
    clip: auto;
    clip-path: none;
    white-space: normal;
    font-size: 0.9rem;
    font-weight: 700;
    letter-spacing: 0.01em;
    color: inherit;
  }
  .prose .footnotes p {
    margin-block: 0.4rem;
  }
  .prose .footnotes a {
    color: inherit;
    text-underline-offset: 2px;
  }
  .prose .footnotes a.data-footnote-backref {
    text-decoration: none;
  }
  /* Parley transcript folds (built by parleyFoldsRemarkPlugin): the reasoning,
     summary and tool blocks an agentic loop leaves behind. Apparatus, not prose
     — collapsed by default, and styled to sit beside the conversation rather
     than in it. The marker glyph is the only color the row needs. */
  .prose details.parley-fold {
    margin-block: 0.9rem;
    padding-left: 0.85rem;
    border-left: 2px solid rgb(203 213 225 / 0.8); /* slate-300 */
    font-size: 0.85rem;
    line-height: 1.55;
    color: rgb(100 116 139); /* slate-500 */
  }
  .prose details.parley-fold > summary {
    cursor: pointer;
    list-style: none; /* the ▸/▾ below replaces the default disclosure marker */
    font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
    font-size: 0.8rem;
    -webkit-user-select: none;
       -moz-user-select: none;
            user-select: none;
  }
  .prose details.parley-fold > summary::-webkit-details-marker {
    display: none;
  }
  .prose details.parley-fold > summary::after {
    content: ' ▸';
  }
  .prose details.parley-fold[open] > summary::after {
    content: ' ▾';
  }
  .prose details.parley-fold > summary:hover {
    color: rgb(51 65 85); /* slate-700 */
  }
  /* Tighter than body copy, and no oversized code inside a fold. */
  .prose details.parley-fold > :not(summary) {
    margin-block: 0.5rem;
  }
  .prose details.parley-fold pre {
    font-size: 0.78rem;
  }
  .dark .prose details.parley-fold {
    border-left-color: rgb(51 65 85 / 0.8); /* slate-700 */
    color: rgb(148 163 184); /* slate-400 */
  }
  .dark .prose details.parley-fold > summary:hover {
    color: rgb(203 213 225); /* slate-300 */
  }
  /* KaTeX display math on narrow screens: scroll horizontally (math can't
     auto-wrap mid-expression), with a visible scrollbar AND an edge shadow that
     appears only when the equation overflows — so it's obvious there's more to
     scroll, even with iOS's fade-away overlay scrollbars. Cover color is the
     page bg (var adapts to dark mode); shadows are slate (readable on both). */
  .prose .katex-display {
    max-width: 100%;
    overflow-x: auto;
    overflow-y: hidden;
    padding-block: 0.5rem; /* room so the scrollbar doesn't clip descenders */
    scrollbar-width: thin;
    scrollbar-color: rgb(148 163 184 / 0.8) rgb(148 163 184 / 0.2);
    background:
      linear-gradient(to right, var(--aw-color-bg-page), transparent) 0 0 / 28px 100% no-repeat local,
      linear-gradient(to left, var(--aw-color-bg-page), transparent) 100% 0 / 28px 100% no-repeat local,
      radial-gradient(farthest-side at 0 50%, rgb(100 116 139 / 0.3), transparent) 0 0 / 14px 100% no-repeat scroll,
      radial-gradient(farthest-side at 100% 50%, rgb(100 116 139 / 0.3), transparent) 100% 0 / 14px 100% no-repeat scroll;
  }
  .prose .katex-display::-webkit-scrollbar { height: 8px; }
  .prose .katex-display::-webkit-scrollbar-track { background: rgb(148 163 184 / 0.2); border-radius: 4px; }
  .prose .katex-display::-webkit-scrollbar-thumb { background: rgb(148 163 184 / 0.75); border-radius: 4px; }
  @media (max-width: 640px) {
    .prose .katex-display > .katex {
      font-size: 0.9em; /* a touch smaller on phones, fewer equations need scrolling */
    }
  }

(function () {
