    }).forEach(([k, v]) => s.setAttribute(k, v));
    container.appendChild(s);
  };

  // Push theme updates into the giscus iframe when the site theme toggles
  const updateTheme = () => {
    const iframe = document.querySelector('iframe.giscus-frame');
