	display: block;
}

#dropdown button {
	border: 0;
	background: transparent;
	color: white;
	font-family: system-ui, sans-serif;
	font-size: 14px;
	white-space: nowrap;
	text-decoration: none;
	margin: 0;
	display: flex;
	align-items: center;
	width: 100%;
	padding: 8px;
	border-radius: 8px;
}

#dropdown button:hover, #dropdown button:focus-visible {
	background: #FFFFFF20;
	cursor: pointer;
}

#dropdown button.active {
	background: rgba(71, 78, 94, 1);
}

#dropdown .icon {
	position: relative;
	height: 20px;
	width: 20px;
	padding: 1px;
